Q: Ghost cms youtube video embed size A: <p>This will do it for you:</p>
<pre><code>&lt;script&gt;
  document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('iframe[src*=&quot;youtube.com/embed&quot;]').forEach(function(iframe) {
      var aspectRatio = (iframe.height / iframe.width) * 100;
      var wrapper = document.createElement('div');
      wrapper.style.position = 'relative';
      wrapper.style.paddingBottom = aspectRatio + '%';
      wrapper.style.height = '0';
      wrapper.style.overflow = 'hidden';
      wrapper.style.maxWidth = '100%';
      iframe.style.position = 'absolute';
      iframe.style.top = '0';
      iframe.style.left = '0';
      iframe.style.width = '100%';
      iframe.style.height = '100%';
      iframe.removeAttribute('width');
      iframe.removeAttribute('height');
      iframe.parentNode.insertBefore(wrapper, iframe);
      wrapper.appendChild(iframe);
    });
  });
&lt;/script&gt;
</code></pre>

Q: How to put 100-digit integer in a loop and add +1 on each cycle? A: <p>You need a <code>BigInteger</code> representation class to represent large numbers and perform mathematical operations on them.. <code>GNU Multiple Precision Arithmetic Library</code> would be able to do what you are asking better than any answer we could give you..</p>

<p>However, for a naive solution, you can use the following which I wrote just for fun.. It works :D  I only support addition just for this answer and it does not support addition of a "negative" which is subtraction. Plain addition will work.</p>

<p>Note: It is not the most efficient way to implement <code>BigInteger</code> arithmetic, but it should be fine for an answer. If you want efficiency, check out: <a href="https://gmplib.org/" rel="nofollow noreferrer">https://gmplib.org/</a></p>

<pre><code>//
//  main.cpp
//  BigSimpleInteger
//
//  Created by Brandon Anthony on 2017-09-11.
//

#include &lt;algorithm&gt;
#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;stdexcept&gt;
#include &lt;cstring&gt;
#include &lt;thread&gt;


class BigInteger
{
private:
    char sign;
    std::string digits;
    const std::size_t base = 10;
    short toDigit(std::size_t index) const {return index &lt; digits.size() ? digits[index] - '0' : 0;}
    void Normalise();
    inline bool isPositive() const {return sign == '+';}
    inline bool isNeutral() const {return sign == '~';}

public:
    BigInteger();
    BigInteger(int value);
    BigInteger(int64_t value);
    BigInteger(const std::string &amp;value);
    BigInteger(const BigInteger &amp;other);

    bool operator == (const BigInteger &amp;other) const;
    bool operator != (const BigInteger &amp;other) const;

    BigInteger&amp; operator = (const BigInteger &amp;other);
    BigInteger&amp; operator += (const BigInteger &amp;other);

    friend std::ostream&amp; operator &lt;&lt; (std::ostream&amp; os, const BigInteger&amp; other);
};

BigInteger::BigInteger() : sign('~'), digits(1, '0') {}

BigInteger::BigInteger(int value) : BigInteger(static_cast&lt;int64_t&gt;(value)) {}

BigInteger::BigInteger(int64_t value) : sign(value == 0 ? '~' : value &gt; 0 ? '+' : '-'), digits(std::to_string(value))
{
    std::reverse(digits.begin(), digits.end());
}

BigInteger::BigInteger(const std::string &amp;value) : sign('~'), digits(value)
{
    sign = digits.empty() ? '~' : digits[0] == '-' ? '-' : '+';
    if (digits[0] == '+' || digits[0] == '-') digits.erase(0, 1);

    std::reverse(digits.begin(), digits.end());
    Normalise();
    for (std::size_t I = 0; I &lt; digits.size(); ++I)
    {
        if (!isdigit(digits[I]))
        {
            sign = '~';
            digits = "0";
            break;
        }
    }
}

BigInteger::BigInteger(const BigInteger &amp;other) : sign(other.sign), digits(other.digits) {}

void BigInteger::Normalise()
{
    for (int I = static_cast&lt;int&gt;(digits.size()) - 1; I &gt;= 0; --I)
    {
        if (digits[I] != '0') break;
        digits.erase(I, 1);
    }

    if (digits.empty())
    {
        digits = "0";
        sign = '~';
    }
}

bool BigInteger::operator == (const BigInteger &amp;other) const
{
    if (sign != other.sign || digits.size() != other.digits.size())
        return false;

    for (int I = static_cast&lt;int&gt;(digits.size()) - 1; I &gt;= 0; --I)
    {
        if (toDigit(I) != other.toDigit(I))
            return false;
    }
    return true;
}

bool BigInteger::operator != (const BigInteger &amp;other) const
{
    return !(*this == other);
}

BigInteger&amp; BigInteger::operator = (const BigInteger &amp;other)
{
    sign = other.sign;
    digits = other.digits;
    return *this;
}


BigInteger&amp; BigInteger::operator += (const BigInteger &amp;other)
{
    if (other.isNeutral())
    {
        return *this;
    }

    if (sign != other.sign)
    {
        //return *this -= (other * -1);
        throw std::runtime_error("Subtraction (Additon of a negative) not supported");
    }

    int carry = 0, total = 0;
    std::size_t length = std::max(digits.size(), other.digits.size());

    for (std::size_t I = 0; I &lt; length; ++I)
    {
        total = toDigit(I) + other.toDigit(I) + carry;
        carry = total / base;
        total %= base;

        if (I &gt;= digits.size())
        {
            digits.resize(digits.size() + 1);
        }

        digits[I] = total + '0';
    }

    if (carry)
    {
        digits.resize(digits.size() + 1);
        digits[digits.size() - 1] = carry + '0';
    }
    return *this;
}

std::ostream&amp; operator &lt;&lt; (std::ostream&amp; os, const BigInteger&amp; other)
{
    if (other.sign == '-') os &lt;&lt; '-';
    std::string temp = other.digits;
    std::reverse(temp.begin(), temp.end());
    return os &lt;&lt; temp;
}




int main(int argc, const char * argv[]) {

    BigInteger bi{"888888888888888888888888888888888888888888888888888888888888888"};
    BigInteger ti{"999999999999999999999999999999999999999999999999999999999999999"};

    std::cout&lt;&lt;bi&lt;&lt;"\n";

    while (bi != ti)
    {
        bi += 1;
        std::cout&lt;&lt;bi&lt;&lt;"\n";
    }

    return 0;
}
</code></pre>
